-- Cópia mínima do CONTRATO de site_metrics_events verificado em 21/11/2026.
-- Banco descartável criado no runner; não conecta ao Supabase do cliente.
CREATE ROLE anon NOLOGIN;
GRANT USAGE ON SCHEMA public TO anon;

CREATE TABLE public.site_metrics_events (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  event_type text NOT NULL,
  product_name text NOT NULL DEFAULT '',
  page_path text NOT NULL DEFAULT '',
  referrer text NOT NULL DEFAULT '',
  client_id text NOT NULL DEFAULT '',
  session_id text NOT NULL DEFAULT '',
  created_at timestamptz NOT NULL DEFAULT now(),
  city text NOT NULL DEFAULT '',
  region text NOT NULL DEFAULT '',
  country text NOT NULL DEFAULT '',
  device_type text NOT NULL DEFAULT '',
  browser text NOT NULL DEFAULT '',
  traffic_source text NOT NULL DEFAULT '',
  utm_source text NOT NULL DEFAULT '',
  utm_medium text NOT NULL DEFAULT '',
  utm_campaign text NOT NULL DEFAULT '',
  entry_path text NOT NULL DEFAULT '',
  event_context text NOT NULL DEFAULT '',
  CONSTRAINT site_metrics_events_event_type_check CHECK (
    event_type IN ('page_view','product_open','whatsapp_click','search',
                   'gallery_open','occasion_filter','category_filter')
  )
);
ALTER TABLE public.site_metrics_events ENABLE ROW LEVEL SECURITY;
GRANT INSERT ON public.site_metrics_events TO anon;
CREATE POLICY public_insert_site_metrics
ON public.site_metrics_events FOR INSERT TO anon
WITH CHECK (
  event_type IN ('page_view','product_open','whatsapp_click','search',
                 'gallery_open','occasion_filter','category_filter')
  AND length(product_name)<=180
  AND length(page_path)<=300
  AND length(referrer)<=500
  AND length(client_id)<=100
  AND length(session_id)<=100
  AND length(city)<=120
  AND length(region)<=120
  AND length(country)<=80
  AND length(device_type)<=40
  AND length(browser)<=60
  AND length(traffic_source)<=120
  AND length(utm_source)<=120
  AND length(utm_medium)<=120
  AND length(utm_campaign)<=180
  AND length(entry_path)<=300
  AND length(event_context)<=80
);
